/**
 * Tenant Data Validation Module
 * 
 * Validates tenant data before provisioning to ensure:
 * - Required fields are present
 * - Tenant ID format is correct (lowercase alphanumeric, 5-36 chars)
 * - Email addresses are valid
 * - No SQL injection or XSS vulnerabilities
 */

const TENANT_ID_REGEX = /^[a-z0-9]{5,36}$/;
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Validate tenant creation data
 */
export function validateTenantData(event) {
  const body = typeof event.body === 'string' ? JSON.parse(event.body) : event.body;
  const data = body.data || body;
  
  const errors = [];
  
  // Required fields
  if (!data.tenantId) {
    errors.push('tenantId is required');
  } else if (!TENANT_ID_REGEX.test(data.tenantId)) {
    errors.push('tenantId must be lowercase letters and numbers only (5-36 chars)');
  }
  
  if (!data.tenantName) {
    errors.push('tenantName is required');
  } else if (data.tenantName.length > 100) {
    errors.push('tenantName must be max 100 characters');
  }
  
  if (!data.contactEmail) {
    errors.push('contactEmail is required');
  } else if (!EMAIL_REGEX.test(data.contactEmail)) {
    errors.push('contactEmail must be a valid email address');
  }
  
  if (!data.orgId) {
    errors.push('orgId is required');
  } else if (!/^[a-z0-9]{5,36}$/.test(data.orgId)) {
    errors.push('orgId must be lowercase letters and numbers only (5-36 chars)');
  }
  
  // adminEmail is optional: an IT Svc Org (SPA) user may manage the tenant
  // without a dedicated tenant admin. When omitted, registerTenantWithASM
  // sends the requester (contactEmail) as newTenantAdminEmail, which ASM
  // requires. Normalize first so non-string / whitespace-only input is
  // treated as blank instead of throwing or failing the format check.
  const adminEmail =
    typeof data.adminEmail === 'string' ? data.adminEmail.trim().toLowerCase() : '';
  if (adminEmail && !EMAIL_REGEX.test(adminEmail)) {
    errors.push('adminEmail must be a valid email address');
  }

  // licenseKey is optional: the self-signup orchestrator passes the billing
  // license key, which registerTenantWithASM forwards as kvLicenseKey. When
  // omitted (admin-created tenants, UC II billing is Phase 2) ASM issues a
  // 5-user test license. Opaque string, no whitespace, bounded length.
  // Only an ABSENT field means "no license" (admin-created tenants, ASM
  // issues a test license). A field that is present but null, blank, or
  // not a string is a 400: a self-signup whose key went missing must fail
  // loudly, never silently get a test license.
  let licenseKey;
  if (data.licenseKey !== undefined) {
    if (typeof data.licenseKey !== 'string') {
      errors.push('licenseKey must be a non-empty string when present');
    } else {
      licenseKey = data.licenseKey.trim();
      if (!licenseKey) {
        errors.push('licenseKey must be a non-empty string when present');
      } else if (licenseKey.length > 200 || /\s/.test(licenseKey)) {
        errors.push('licenseKey must be a single token of at most 200 characters');
      }
    }
  }
  
  if (errors.length > 0) {
    const error = new Error(`Validation failed: ${errors.join(', ')}`);
    error.statusCode = 400;
    error.code = 'validation_error';
    error.validationErrors = errors;
    throw error;
  }
  
  // Return sanitized data
  return {
    tenantId: data.tenantId.toLowerCase(), // Normalize to lowercase
    tenantName: data.tenantName.trim(),
    contactEmail: data.contactEmail.toLowerCase().trim(),
    orgId: data.orgId.toLowerCase(),
    samlproxy: data.samlproxy !== false, // Default to true
    adminEmail: adminEmail || undefined,
    licenseKey: licenseKey || undefined,
    adminFirstName: data.adminFirstName?.trim(),
    adminLastName: data.adminLastName?.trim(),
  };
}

/**
 * Validate tenant ID uniqueness
 */
export function validateTenantIdFormat(tenantId) {
  if (!TENANT_ID_REGEX.test(tenantId)) {
    throw new Error('Invalid tenant ID format');
  }
  return tenantId.toLowerCase();
}

/**
 * Sanitize string for storage (prevent XSS)
 */
export function sanitizeString(str) {
  if (!str) return str;
  return str
    .replace(/[<>]/g, '') // Remove angle brackets
    .trim();
}

export default validateTenantData;
